            "content": "# Function to determine the maximum number of reachable nodes in an undirected graph

from collections import defaultdict, deque

def max_reachable_nodes(n, edges, restricted):
    # Create an adjacency list for the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Set of restricted nodes for quick lookup
    restricted_set = set(restricted)

    # BFS or DFS to count reachable nodes
    queue = deque([0])  # Start from node 0
    visited = set([0])  # Keep track of visited nodes
    count = 0

    while queue:
        node = queue.popleft()
        count += 1  # Count this node

        for neighbor in graph[node]:
            if neighbor not in visited and neighbor not in restricted_set:
                visited.add(neighbor)
                queue.append(neighbor)

    return count
